class Lookup
  attr_reader :calls
  def initialize
    @calls = 0
    @cache = {}
  end

  def find(k)
    @cache[k] ||= begin
      @calls += 1
      k.even?
    end
  end
end

l = Lookup.new
3.times { l.find(2) }
3.times { l.find(3) }
puts l.calls

